'use client';

import {useEffect,useMemo,useRef,useState,type CSSProperties} from 'react';
import {flushSync} from 'react-dom';
import {Radar,RefreshCw,Plus,SlidersHorizontal,BookOpen,Layers3,Newspaper,Info,Check,TriangleAlert,Trash2,Download,Search,ChevronDown,FileText,ShieldCheck,Clock3,ArrowUpRight,Terminal,Bookmark,Upload,Activity,Library,Zap,ArrowRight,CheckCheck,Sun,Moon,GitCompareArrows,PencilLine} from 'lucide-react';
import {Tabs,TabsList,TabsTrigger,TabsContent} from '@/components/ui/tabs';
import {Dialog,DialogContent,DialogHeader,DialogTitle,DialogDescription} from '@/components/ui/dialog';
import {Select,SelectTrigger,SelectValue,SelectContent,SelectItem} from '@/components/ui/select';
import {Switch} from '@/components/ui/switch';
import {Slider} from '@/components/ui/slider';
import {Checkbox} from '@/components/ui/checkbox';
import {BASE_DATE,seed,topics,historical,monitored,historySource,officialSource,guidanceSource,pndNews,pnd2026PDF,pnd2025PDF,officialDocuments,type Evidence,type Kind} from '@/lib/radar-data';
import {rank,defaultWeights,weightKeys,sanitizeWeights,validEvidence,deduplicate,classify,safeURL,canonicalURL,eligible,publisher,normalize,validDay,type Weights} from '@/lib/radar-model';
import type {Collection,SourceStatus} from '@/lib/collector';

const labels:Record<string,string>={editorial:'Apostas docentes',news:'Atualidades',history:'Histórico de eixos',institutional:'Provas relacionadas',hint:'Pistas não verificadas'};
const fmt=(n:number)=>n.toLocaleString('pt-BR',{minimumFractionDigits:1,maximumFractionDigits:1});
const day=(s:string|null)=>s?new Date(s.slice(0,10)+'T12:00:00Z').toLocaleDateString('pt-BR',{timeZone:'UTC'}):'Sem data identificada';
const today=()=>new Date().toLocaleDateString('en-CA',{timeZone:'America/Sao_Paulo'});
const storageKey='kalore-radar-v2';
type Tab='radar'|'dossie'|'oficial'|'fontes'|'historico'|'plano'|'metodo';
const tabs:Tab[]=['radar','dossie','oficial','fontes','historico','plano','metodo'];
const tabNames:Record<Tab,string>={radar:'Radar de temas',dossie:'Dossiê PND',oficial:'Biblioteca do Inep',fontes:'Fontes e evidências',historico:'Histórico do exame',plano:'Meu plano de redação',metodo:'Método do Radar'};
function readNotes(value:unknown):Record<string,string>{return value&&typeof value==='object'&&!Array.isArray(value)?Object.fromEntries(Object.entries(value).filter(([id,note])=>topics.some(t=>t.id===id)&&typeof note==='string').map(([id,note])=>[id,(note as string).slice(0,4000)])):{};}
type ModelContext={registerTool:(tool:unknown,options:unknown)=>void|Promise<void>};
const isStatic=()=>typeof window!=='undefined'&&(window as unknown as {__KALORE_STATIC__?:boolean}).__KALORE_STATIC__===true;

function RadarArt(){return <div className="radar-art" aria-hidden="true"><div className="radar-orbit orbit-one"/><div className="radar-orbit orbit-two"/><div className="radar-orbit orbit-three"/><span className="radar-star">✦</span><span className="radar-chip chip-one"><Newspaper size={14}/>Atualidades</span><span className="radar-chip chip-two"><BookOpen size={14}/>Repertório</span><span className="radar-chip chip-three"><FileText size={14}/>Sua redação</span></div>}
function LinkOut({url,children,className=''}:{url:string;children:React.ReactNode;className?:string}){return <a href={safeURL(url)} target="_blank" rel="noreferrer" className={className}>{children}<ArrowUpRight size={16}/></a>}
function saveFile(name:string,content:string,type='application/json'){const object=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=object;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(object),1000)}

export default function Home(){
 const [theme,setTheme]=useState<'dark'|'light'>(()=>typeof document!=='undefined'&&document.documentElement.dataset.theme==='light'?'light':'dark');const firstTab=useRef(true);
 useEffect(()=>{document.documentElement.dataset.theme=theme;try{localStorage.setItem('kalore-color-theme',theme)}catch{}},[theme]);
 useEffect(()=>{const update=(e:StorageEvent)=>{if(e.key==='kalore-color-theme'&&(e.newValue==='dark'||e.newValue==='light'))setTheme(e.newValue)};window.addEventListener('storage',update);return()=>window.removeEventListener('storage',update)},[]);
 useEffect(()=>window.KaloreMotion?.init(document.querySelector('.app-shell')||document),[]);
 const [tab,setTab]=useState<Tab>(()=>{const value=typeof location==='undefined'?'radar':location.hash.slice(1);return tabs.includes(value as Tab)?value as Tab:'radar'});
 useEffect(()=>{const update=()=>{const next=location.hash.slice(1);if(tabs.includes(next as Tab))setTab(next as Tab)};window.addEventListener('hashchange',update);return()=>window.removeEventListener('hashchange',update)},[]);
 useEffect(()=>{if(firstTab.current){firstTab.current=false;return;}window.KaloreMotion?.enter(document.querySelector('[data-slot="tabs-content"][data-state="active"]'))},[tab]);const [selected,setSelected]=useState('digital');const [allRows,setAllRows]=useState(false);const [query,setQuery]=useState('');
 const [notes,setNotes]=useState<Record<string,string>>({});const [notesSaved,setNotesSaved]=useState(true);const [compareOpen,setCompareOpen]=useState(false);const [compareIds,setCompareIds]=useState<[string,string]>(['digital','leitura']);
 useEffect(()=>{if(compareOpen)requestAnimationFrame(()=>window.KaloreMotion?.enter(document.querySelector('.compare-dialog')))},[compareOpen]);
 const [custom,setCustom]=useState<Evidence[]>([]);const [collected,setCollected]=useState<Evidence[]>([]);const [weights,setWeights]=useState<Weights>(defaultWeights);const [hints,setHints]=useState(false);const [institutional,setInstitutional]=useState(true);const [animations,setAnimations]=useState(true);
 const [cutoff,setCutoff]=useState(BASE_DATE);const [loaded,setLoaded]=useState(false);const [busy,setBusy]=useState(false);const [status,setStatus]=useState<SourceStatus[]>([]);const [lastFetch,setLastFetch]=useState('');const [message,setMessage]=useState('');const [portable,setPortable]=useState(false);
 const [addOpen,setAddOpen]=useState(false);const [settingsOpen,setSettingsOpen]=useState(false);const [title,setTitle]=useState('');const [url,setUrl]=useState('');const [date,setDate]=useState('');const [text,setText]=useState('');const [kind,setKind]=useState<Kind>('hint');const [chosen,setChosen]=useState<string[]>([]);const [formError,setFormError]=useState('');
 const [sourceFilter,setSourceFilter]=useState('all');const [sourceQuery,setSourceQuery]=useState('');const [historyQuery,setHistoryQuery]=useState('');const [favorites,setFavorites]=useState<string[]>([]);const [completed,setCompleted]=useState<string[]>([]);const importRef=useRef<HTMLInputElement>(null);

 useEffect(()=>{setCutoff(today());setPortable(isStatic());try{const raw=localStorage.getItem(storageKey)||localStorage.getItem('radar-enem-v1');if(raw){const d=JSON.parse(raw);setNotes(readNotes(d.notes));if(Array.isArray(d.custom))setCustom(d.custom.filter(validEvidence).slice(0,500).map((e:Evidence)=>({...e,origin:'personal'})));if(Array.isArray(d.collected))setCollected(d.collected.filter(validEvidence).slice(0,500));if(typeof d.hints==='boolean')setHints(d.hints);if(typeof d.institutional==='boolean')setInstitutional(d.institutional);if(typeof d.animations==='boolean')setAnimations(d.animations);setWeights(sanitizeWeights(d.weights));if(typeof d.lastFetch==='string'&&Number.isFinite(Date.parse(d.lastFetch)))setLastFetch(d.lastFetch);for(const [key,set] of [['favorites',setFavorites],['completed',setCompleted]] as const)if(Array.isArray(d[key]))set([...new Set<string>(d[key].filter((id:unknown)=>typeof id==='string'&&topics.some(t=>t.id===id)))]);}}catch{setMessage('Não foi possível recuperar seus ajustes. A base inicial continua disponível.')}try{const motion=localStorage.getItem('kalore-motion');if(motion==='true'||motion==='false')setAnimations(motion==='true')}catch{}setLoaded(true)},[]);
 useEffect(()=>{if(!loaded)return;try{localStorage.setItem(storageKey,JSON.stringify({custom,collected,weights,hints,institutional,animations,lastFetch,favorites,completed,notes}));setNotesSaved(true)}catch{setNotesSaved(false);setMessage('O navegador não permitiu salvar os ajustes. Exporte uma cópia para guardar seu progresso.')}},[custom,collected,weights,hints,institutional,animations,lastFetch,favorites,completed,notes,loaded]);
 useEffect(()=>{if(!loaded)return;try{localStorage.setItem('kalore-motion',String(animations))}catch{}document.documentElement.classList.toggle('motion-off',!animations)},[animations,loaded]);
 useEffect(()=>{const update=(e:StorageEvent)=>{if(e.key==='kalore-motion')setAnimations(e.newValue!=='false')};window.addEventListener('storage',update);return()=>window.removeEventListener('storage',update)},[]);
 useEffect(()=>{if(loaded&&location.hash!=='#'+tab)history.pushState(null,'','#'+tab)},[tab,loaded]);

 const evidence=useMemo(()=>deduplicate([...seed,...custom,...collected]),[custom,collected]);
 const ranking=useMemo(()=>rank(evidence,weights,hints,cutoff,institutional),[evidence,weights,hints,cutoff,institutional]);
 const withoutPND=useMemo(()=>rank(evidence,weights,hints,cutoff,false),[evidence,weights,hints,cutoff]);
 const withPND=useMemo(()=>rank(evidence,weights,hints,cutoff,true),[evidence,weights,hints,cutoff]);
 const current=ranking.find(t=>t.id===selected)||ranking[0];const top=ranking[0];
 const comparison=compareIds.map(id=>ranking.find(t=>t.id===id)||ranking[0]);
 function openComparison(){setCompareIds([current.id,ranking.find(t=>t.id!==current.id)!.id]);setCompareOpen(true)}
 function exportComparison(){saveFile('kalore-comparacao-de-temas.md','# Comparação para estudo · Kaloré\n\nÍndices relativos, sem probabilidade de cair. Base de '+day(cutoff)+'; mesmos pesos para os dois temas.\n\n'+comparison.map(t=>'## '+t.title+'\n\nÍndice: '+fmt(t.percent)+'% · '+t.groups+' grupos de fontes\n\nProposta: '+t.proposal+'\n\n'+weightKeys.map(k=>'- '+labels[k]+': +'+fmt(t.points[k])+' pontos').join('\n')+'\n\nMinhas anotações: '+(notes[t.id]||'Ainda sem anotações.')+'\n\nFontes:\n'+t.related.map(e=>'- '+e.title+': '+e.url).join('\n')).join('\n\n'),'text/markdown')}
 const active=evidence.filter(e=>eligible(e,cutoff)&&(hints||e.kind!=='hint')&&(institutional||e.kind!=='institutional'));
 const shown=ranking.filter(t=>normalize(t.title+' '+t.axis).includes(normalize(query)));
 const readingWith=withPND.find(t=>t.id==='leitura')!;const readingWithout=withoutPND.find(t=>t.id==='leitura')!;
 const visibleSources=evidence.filter(e=>(sourceFilter==='all'||e.kind===sourceFilter||sourceFilter==='personal'&&e.origin==='personal')&&normalize(e.title+' '+e.source+' '+e.note).includes(normalize(sourceQuery)));
 const snapshot=useRef({ranking,evidence,cutoff});snapshot.current={ranking,evidence,cutoff};
 useEffect(()=>{const ctx=(document as unknown as {modelContext?:ModelContext}).modelContext;if(!ctx?.registerTool)return;const life=new AbortController();const tools=[{name:'read_theme_ranking',title:'Consultar ranking de temas',description:'Retorna o índice relativo e as fontes do ranking atual. Percentuais não são probabilidades.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute:(input:unknown)=>{if(!input||typeof input!=='object'||Object.keys(input).length)throw new Error('Use um objeto vazio.');return {date:snapshot.current.cutoff,meaning:'Índice relativo de prioridade, sem calibração preditiva',ranking:snapshot.current.ranking.map(r=>({id:r.id,title:r.title,percent:r.percent,sources:r.related.map(e=>e.url)}))}}},{name:'show_theme_analysis',title:'Abrir análise de um tema',description:'Seleciona um tema e abre sua análise no radar.',inputSchema:{type:'object',properties:{topicId:{type:'string',enum:topics.map(t=>t.id)}},required:['topicId'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute:(input:unknown)=>{const p=input as {topicId?:string};if(!p||Object.keys(p).some(k=>k!=='topicId')||!topics.some(t=>t.id===p.topicId))throw new Error('Tema desconhecido.');flushSync(()=>{setSelected(p.topicId!);setTab('radar')});return {selectedTopic:p.topicId,view:'radar'}}}];for(const tool of tools){try{Promise.resolve(ctx.registerTool(tool,{signal:life.signal})).catch(()=>{})}catch{}}return()=>life.abort()},[]);

 async function refresh(){if(busy)return;setBusy(true);const staticMode=isStatic();setMessage(staticMode?'Carregando a base publicada…':'Consultando fontes públicas…');try{const r=await fetch(staticMode?'./data/latest.json':'/api/collect',{cache:'no-store',signal:AbortSignal.timeout(25000)});if(!r.ok)throw new Error();const d=await r.json() as Collection&{cached?:boolean};if(!Array.isArray(d.articles)||d.articles.length>500||!d.articles.every(validEvidence)||!Array.isArray(d.statuses)||typeof d.fetchedAt!=='string'||!Number.isFinite(Date.parse(d.fetchedAt)))throw new Error();setCollected(prev=>deduplicate([...d.articles,...prev]).slice(0,500));setStatus(d.statuses.filter(s=>s&&typeof s.id==='string'&&typeof s.ok==='boolean'&&typeof s.message==='string'));setLastFetch(d.fetchedAt);setCutoff(today());const good=d.statuses.filter(s=>s.ok).length;setMessage(staticMode?`Base publicada em ${day(d.fetchedAt)} carregada. Esta versão usa um arquivo de dados; a coleta externa é feita pelo script do projeto.`:good===0?'Nenhuma fonte respondeu. A base anterior foi mantida.':`${good}/${d.statuses.length} fontes responderam · ${d.articles.length} registros recebidos.${d.cached?' Consulta recente reutilizada.':''}${good<d.statuses.length?' Confira as falhas em Fontes.':''}`)}catch{setMessage('Não foi possível atualizar agora. A base anterior foi mantida.')}finally{setBusy(false)}}
 function openTopic(id:string){setSelected(id);setTab('radar');if(window.matchMedia('(max-width:900px)').matches)requestAnimationFrame(()=>document.getElementById('theme-analysis')?.scrollIntoView({behavior:animations&&!window.matchMedia('(prefers-reduced-motion: reduce)').matches?'smooth':'auto',block:'start'}))}
 function toggleFavorite(id:string){setFavorites(p=>p.includes(id)?p.filter(x=>x!==id):[...p,id]);}
 function exportData(){saveFile('kalore-radar-'+cutoff+'.json',JSON.stringify({schemaVersion:2,targetYear:2026,asOf:cutoff,meaning:'Índice relativo de prioridade de estudo; não é probabilidade de cair.',weights,hints,institutional,animations,custom,collected,lastFetch,favorites,completed,notes,evidence,ranking:ranking.map(r=>({id:r.id,title:r.title,percent:r.percent,score:r.score,points:r.points}))},null,2));}
 async function importData(file?:File){if(!file)return;try{if(file.size>2_000_000)throw new Error('Arquivo acima de 2 MB.');const d=JSON.parse(await file.text());if(![1,2].includes(d.schemaVersion)||d.targetYear!==2026)throw new Error('Use um arquivo exportado pelo radar de 2026.');const personal=d.custom??(Array.isArray(d.evidence)?d.evidence.filter((e:Evidence)=>e.origin==='personal'):[]);const incoming=d.collected??[];if(!Array.isArray(personal)||!Array.isArray(incoming)||personal.length+incoming.length>1000||![...personal,...incoming].every(validEvidence))throw new Error('Há registros inválidos no arquivo.');setCustom(p=>deduplicate([...p,...personal.map((e:Evidence)=>({...e,origin:'personal' as const}))]).slice(0,500));setCollected(p=>deduplicate([...p,...incoming]).slice(0,500));setWeights(sanitizeWeights(d.weights));setHints(d.hints===true||d.includeHints===true);if(typeof d.institutional==='boolean')setInstitutional(d.institutional);if(d.notes!==undefined)setNotes(readNotes(d.notes));if(Array.isArray(d.favorites))setFavorites([...new Set<string>(d.favorites.filter((id:unknown)=>typeof id==='string'&&topics.some(t=>t.id===id)))]);if(Array.isArray(d.completed))setCompleted([...new Set<string>(d.completed.filter((id:unknown)=>typeof id==='string'&&topics.some(t=>t.id===id)))]);setMessage('Cópia importada. Suas fontes foram combinadas e os ajustes restaurados.');}catch(e){setMessage(e instanceof Error?e.message:'Não foi possível importar o arquivo.')}finally{if(importRef.current)importRef.current.value='';}}
 function submit(e:React.FormEvent){e.preventDefault();setFormError('');if(title.trim().length<5||!chosen.length){setFormError('Escreva um título e escolha pelo menos um tema.');return}if(url&&!safeURL(url)){setFormError('Use um endereço http ou https válido, sem credenciais.');return}if(date&&(!validDay(date)||date>today())){setFormError('Informe uma data válida, até hoje.');return}const item:Evidence={id:'personal-'+crypto.randomUUID(),title:title.trim(),url:safeURL(url),source:url?publisher(url):'Pista pessoal',kind,date:date||null,observedAt:today(),topics:chosen,note:text.trim()||'Adicionado por você; conteúdo não verificado pelo aplicativo.',origin:'personal'};if(evidence.some(x=>x.url&&item.url&&canonicalURL(x.url)===canonicalURL(item.url))){setFormError('Esta URL já está na base. Duplicatas não aumentam o índice.');return}setCustom(p=>[item,...p]);setAddOpen(false);setTitle('');setUrl('');setDate('');setText('');setChosen([]);setMessage(kind==='hint'?'Pista adicionada. Ligue “Pistas não verificadas” para incluí-la no cálculo.':'Fonte adicionada e ranking recalculado.');}
 function exportPlan(){const rows=favorites.map(id=>topics.find(t=>t.id===id)!).filter(Boolean);saveFile('kalore-plano-de-redacao.md','# Meu plano de redação · Kaloré\n\nFeito por Kaloré, para todos.\n\n'+rows.map((t,i)=>`## Sessão ${i+1} · ${t.title}\n\n- [${completed.includes(t.id)?'x':' '}] Redação concluída\n- 10 min: conferir as fontes e reunir dois repertórios.\n- 10 min: definir tese, dois argumentos e intervenção.\n- 40 min: escrever o texto.\n- 15 min: revisar as cinco competências com a cartilha do Inep.\n\nProposta de treino: ${t.proposal}\n\n${notes[t.id]?"Minhas anotações:\n"+notes[t.id]+"\n\n":""}${t.angles.map(a=>'- '+a).join('\n')}\n\nFontes:\n${ranking.find(r=>r.id===t.id)!.related.map(e=>'- '+e.title+': '+e.url).join('\n')||'- Consulte a biblioteca oficial e procure repertório complementar.'}`).join('\n\n')+'\n\nCartilha: '+guidanceSource+'\n\nOs percentuais do radar são prioridades de estudo, sem calibração preditiva.\n','text/markdown');}
 function sourceCard(e:Evidence){return <article className="source-card panel" key={e.id}><div className="source-top"><span className={'tag kind-'+e.kind}>{labels[e.kind]}</span>{e.origin==='personal'&&<button className="icon-button" aria-label={'Remover '+e.title} onClick={()=>setCustom(p=>p.filter(x=>x.id!==e.id))}><Trash2 size={16}/></button>}</div><h3>{e.url?<LinkOut url={e.url}>{e.title}</LinkOut>:e.title}</h3><p>{e.note}</p><div className="source-meta">{e.source} <span>·</span> {day(e.date)}</div><div className="source-tags">{e.topics.map(id=><button key={id} onClick={()=>openTopic(id)}>{topics.find(t=>t.id===id)?.title}</button>)}</div><small>{e.origin==='curated'?'Curadoria · '+day(BASE_DATE):e.origin==='personal'?'Adicionada por você · sem verificação':'Classificação automática · '+day(e.observedAt)}{!eligible(e,cutoff)?' · Fora da janela atual':''}</small></article>}

 return <div data-view={tab} className={'app-shell '+(!animations?'motion-off':'')}><a className="skip-link" href="#content">Pular para o conteúdo</a>
 <header className="topbar"><div className="topbar-inner"><button className="brand" onClick={()=>setTab('radar')} aria-label="Kaloré, abrir radar"><span className="brand-symbol">K</span><span>kaloré<span className="brand-sub">RADAR DE REDAÇÃO</span></span></button><span className="edition"><span className="status-dot"/>ENEM <b>2026</b><span className="edition-divider">/</span>v4.0</span><div className="product-switch"><a className="active" href="./"><span className="product-full">Radar de temas</span><span className="product-short">Radar</span></a><a href="./estudar.html"><span className="product-full">ENEM Hub</span><span className="product-short">Hub</span></a></div><div className="header-actions"><button className="icon-button theme-toggle" onClick={()=>setTheme(theme==='dark'?'light':'dark')} aria-label="Alternar tema" title={theme==='dark'?'Ativar tema claro':'Ativar tema escuro'}>{theme==='dark'?<Sun size={18}/>:<Moon size={18}/>}</button><button className="icon-button" onClick={()=>importRef.current?.click()} aria-label="Importar análise" title="Importar análise"><Upload size={18}/></button><button className="icon-button" onClick={exportData} aria-label="Exportar análise" title="Exportar análise"><Download size={18}/></button><button className="button compact secondary" onClick={()=>setSettingsOpen(true)}><SlidersHorizontal size={16}/><span>Ajustar radar</span></button></div></div></header>
 <input ref={importRef} type="file" accept="application/json,.json" hidden onChange={e=>void importData(e.target.files?.[0])}/>
 <main id="content" className="main"><div className="radar-bento"><div className="page-intro glow-card"><div><div className="eyebrow">IDEIAS PARA A SUA PRÓXIMA REDAÇÃO</div><h1>Uma boa ideia.<br/><em>Sua próxima redação.</em></h1><p>Investigue os sinais. Entenda o contexto. Escreva com repertório.</p><div className="intro-actions"><button className="button primary" onClick={()=>document.getElementById("radar-workspace")?.scrollIntoView({behavior:animations&&!window.KaloreMotion?.reduced()?"smooth":"instant",block:"start"})}><Radar size={17}/>Explorar meus temas<ArrowRight size={16}/></button><a href="./estudar.html" className="button secondary"><BookOpen size={17}/>Abrir meu espaço de estudo<ArrowUpRight size={16}/></a><button className="button secondary" onClick={refresh} disabled={busy}><RefreshCw size={17} className={busy?'spinning':''}/>{busy?'Consultando…':portable?'Atualizar base':'Atualizar fontes'}<ArrowRight size={16}/></button><span className="date-label"><Clock3 size={14}/>Análise · {day(cutoff)}</span></div></div><div className="intro-visual"><RadarArt/><span className="visual-caption">IDEIAS EM ÓRBITA</span></div></div>
 <div className="learning-callout glow-card"><div><span className="section-code">ENEM HUB · SEU ESPAÇO DE ESTUDO</span><span className="callout-symbol" aria-hidden="true">↗</span><h2>Ideias viram<br/>prática aqui.</h2><p>Provas oficiais, 68 PDFs, redação e revisão em um só lugar.</p></div><div className="learning-shortcuts"><a href="./estudar.html#biblioteca"><Library size={18}/>Biblioteca de PDFs<ArrowRight size={16}/></a><a href="./estudar.html#provas-oficiais"><Clock3 size={18}/>Provas oficiais<ArrowRight size={16}/></a><a href="./estudar.html#redacao"><FileText size={18}/>Escrever redação<ArrowRight size={16}/></a></div></div><div className="stats"><div className="stat"><Layers3/><div><strong>{topics.length}</strong><span>temas no radar</span></div><span className="stat-code">01</span></div><div className="stat"><Newspaper/><div><strong>{active.length}</strong><span>evidências ativas</span></div><span className="stat-code">02</span></div><div className="stat"><BookOpen/><div><strong>{historical.length}</strong><span>edições no histórico</span></div><span className="stat-code">03</span></div><button className="stat stat-link" onClick={()=>setTab('oficial')}><ShieldCheck/><div><strong>{officialDocuments.length}</strong><span>referências do Inep</span></div><ArrowUpRight size={17}/></button></div>
 </div><div className="notice"><Info size={16}/><p><strong>Prioridade de estudo.</strong> Os índices somam 100%; não são probabilidades de cair na prova.</p><button onClick={()=>setTab('metodo')}>Ver método<ArrowUpRight size={14}/></button></div>
 {message&&<div role="status" className="status-message"><Activity size={17}/><span>{message}</span>{!busy&&<button onClick={()=>setMessage('')} aria-label="Fechar aviso">×</button>}</div>}
 <div className="radar-workspace-title"><button className="button secondary" onClick={()=>setTab("radar")}><ArrowRight size={14}/>Voltar ao Radar</button><h1>{tabNames[tab]}</h1></div>
 <Tabs value={tab} onValueChange={v=>setTab(v as Tab)}><div className="nav-wrap"><TabsList variant="line" className="main-tabs"><TabsTrigger value="radar"><Radar/>Radar</TabsTrigger><TabsTrigger value="dossie"><Zap/>Dossiê PND<span className="tab-dot"/></TabsTrigger><TabsTrigger value="oficial"><Library/>Inep</TabsTrigger><TabsTrigger value="fontes"><Newspaper/>Fontes</TabsTrigger><TabsTrigger value="historico"><Clock3/>Histórico</TabsTrigger><TabsTrigger value="plano"><Bookmark/>Meu plano{favorites.length>0&&<span className="tab-count">{favorites.length}</span>}</TabsTrigger><TabsTrigger value="metodo"><SlidersHorizontal/>Método</TabsTrigger></TabsList></div>

 <TabsContent value="radar"><div className="workspace reveal" id="radar-workspace"><section className="ranking panel" aria-busy={busy}>{busy&&<div className="sync-skeleton" aria-hidden="true"><span className="glow-skeleton"/><span className="glow-skeleton"/><span className="glow-skeleton"/></div>}<div className="panel-heading"><div><span className="section-code">01 / MAPA DE PRIORIDADES</span><h2>Temas em movimento</h2></div><div className="ranking-tools"><button className="icon-button" aria-label="Comparar temas" title="Comparar temas" onClick={openComparison}><GitCompareArrows size={18}/></button><button className="icon-button" aria-label="Ajustar pesos" onClick={()=>setSettingsOpen(true)}><SlidersHorizontal size={18}/></button></div></div><label className="search-field"><Search size={16}/><input aria-label="Buscar tema ou eixo" placeholder="Buscar tema ou eixo…" value={query} onChange={e=>setQuery(e.target.value)}/><span>{shown.length}</span></label><div className="ranking-head"><span>TEMA / EIXO</span><span>ÍNDICE</span></div><div className="rank-list">{shown.slice(0,allRows||query?topics.length:8).map((t,i)=><button aria-pressed={t.id===current.id} className={'rank-row '+(t.id===current.id?'selected':'')} key={t.id} style={{'--row-delay':`${i*35}ms`} as CSSProperties} onClick={()=>{setSelected(t.id);if(window.matchMedia('(max-width:900px)').matches)openTopic(t.id)}}><span className="position">{String(ranking.findIndex(r=>r.id===t.id)+1).padStart(2,'0')}</span><span className="row-body"><span className="row-title">{t.title}{favorites.includes(t.id)&&<Bookmark size={12}/>}</span><span className="row-meta">{t.axis}<span>·</span>{t.related.length} {t.related.length===1?'fonte':'fontes'}</span><span className="rank-track"><span style={{width:t.percent/top.percent*100+'%'}}/></span></span><span className="percentage">{fmt(t.percent)}<span>%</span></span></button>)}</div>{!shown.length&&<div className="empty-state small"><Search/><p>Nenhum tema para “{query}”.</p><button className="text-button" onClick={()=>setQuery('')}>Limpar busca</button></div>}{!query&&<button className="show-all" onClick={()=>setAllRows(!allRows)}>{allRows?'Mostrar os 8 primeiros':`Explorar os ${topics.length} temas`}<ChevronDown size={16} style={{transform:allRows?'rotate(180deg)':'none'}}/></button>}<div className="ranking-footer"><ShieldCheck size={14}/><span>Contribuição limitada por grupo de fontes.</span></div></section>
 <aside id="theme-analysis" className="analysis panel" aria-label="Análise do tema selecionado"><div className="analysis-label"><span className="tag focus-tag">EM FOCO</span><button className={'icon-button bookmark-button '+(favorites.includes(current.id)?'is-saved':'')} aria-label={favorites.includes(current.id)?'Retirar do plano':'Salvar no meu plano'} title={favorites.includes(current.id)?'Retirar do plano':'Salvar no meu plano'} onClick={()=>toggleFavorite(current.id)}><Bookmark size={19} fill={favorites.includes(current.id)?'currentColor':'none'}/></button></div><span className="axis-label">{current.axis}</span><h2>{current.title}</h2><div className="focus-stat"><strong key={current.id}>{fmt(current.percent)}<span>%</span></strong><div>índice relativo de estudo<small>{current.groups} {current.groups===1?'grupo de fontes':'grupos de fontes'} · {current.related.length} evidências</small></div></div><div className="divider"/><h3>De onde vêm os pontos</h3><div className="factor-list">{weightKeys.map(k=><div className={'factor factor-'+k} key={k}><div><span><i/>{labels[k]}</span><strong>+{fmt(current.points[k])}</strong></div><div className="factor-track"><span style={{width:current.factors[k]*100+'%'}}/></div></div>)}</div><p className="factor-note">+ 10 pontos de base comum. Os pesos são ajustáveis.</p><div className="divider"/><div className="sources-title"><h3>Rastro das evidências</h3><button className="text-button" onClick={()=>{setSourceFilter('all');setSourceQuery('');setTab('fontes')}}>Abrir fontes<ArrowUpRight size={13}/></button></div>{current.related.length?<ul className="evidence-list">{current.related.slice(0,4).map(e=><li key={e.id}>{e.url?<LinkOut url={e.url}><span>{e.source}<small>{labels[e.kind]} · {day(e.date)}</small></span></LinkOut>:<span>{e.title}<small>Pista pessoal</small></span>}</li>)}</ul>:<p className="empty-copy">Sem fonte recente associada nesta seleção. O índice vem da base comum e do histórico do eixo.</p>}<details className="topic-notebook"><summary><span><PencilLine size={17}/>Meus repertórios e argumentos</span><ChevronDown size={16}/></summary><label htmlFor="topic-note">Guarde ideias, referências e conexões para este tema.</label><textarea id="topic-note" value={notes[current.id]||''} maxLength={4000} rows={5} placeholder="Que repertório explica esse problema? Como ele sustenta minha tese?" onChange={e=>setNotes(p=>({...p,[current.id]:e.target.value}))}/><div><span>{notesSaved?'Salvo neste navegador':'Não foi possível salvar'} · {(notes[current.id]||'').length}/4000</span><button className="text-button" disabled={!notes[current.id]} onClick={()=>saveFile('repertorio-'+current.id+'.txt',current.title+'\n\n'+notes[current.id],'text/plain')}><Download size={14}/>Exportar</button></div></details><div className="practice"><div><FileText size={16}/><h3>Uma proposta para treinar</h3></div><p>{current.proposal}</p><ul>{current.angles.map(a=><li key={a}>{a}</li>)}</ul><small>Recorte criado para estudo, sem vínculo com o Inep.</small><button className="button secondary full-width" onClick={()=>toggleFavorite(current.id)}>{favorites.includes(current.id)?<Check size={16}/>:<Plus size={16}/>} {favorites.includes(current.id)?'Adicionado ao meu plano':'Adicionar ao meu plano'}</button><a className="button primary full-width" href={'./estudar.html?tema='+encodeURIComponent(current.proposal)+'#redacao'}><FileText size={16}/>Escrever sobre este tema<ArrowUpRight size={16}/></a></div></aside></div></TabsContent>

 <TabsContent value="dossie"><div className="section-heading"><div><span className="section-code">02 / INVESTIGAÇÃO ABERTA</span><h2>A pista da leitura</h2><p>O que a prova dos professores acrescenta à sua preparação.</p></div><span className="tag kind-institutional"><ShieldCheck size={13}/>Fontes públicas</span></div><div className="dossier-layout"><section className="panel dossier-main"><div className="dossier-banner"><BookOpen size={30}/><div><span className="eyebrow">PND 2026 → LEITURA</span><h3>Ler é assunto de toda a escola.</h3></div></div><p>A análise publicada pelo Instituto Dering em 21/09 descreve uma questão da PND sobre o ensino da leitura em diferentes áreas, com uma atividade de compreensão e leitura como prática social. Esse é um caminho útil para estudar formação de leitores, bibliotecas e acesso a livros.</p><LinkOut url={seed.find(e=>e.id==='pnd-leitura')!.url} className="text-link">Conferir a análise do professor</LinkOut><div className="divider"/><h3>Fato, interpretação, hipótese</h3><div className="finding"><span className="finding-number">01</span><div><strong>Fato oficial: os materiais são públicos</strong><p>O Inep anunciou os cadernos e a grade de correção em 24/09/2026. Você pode consultá-los no acervo da PND.</p><LinkOut url={pndNews} className="text-link">Anúncio do Inep</LinkOut></div></div><div className="finding"><span className="finding-number">02</span><div><strong>Interpretação: a leitura merece repertório</strong><p>O resumo temático usado aqui vem da análise do professor. Os links do caderno oficial foram localizados no portal; confira a questão e seu contexto antes de extrapolar.</p><LinkOut url={pnd2026PDF} className="text-link">Caderno oficial de 2026 · PDF</LinkOut></div></div><div className="finding"><span className="finding-number">03</span><div><strong>Hipótese: pode inspirar um treino para o Enem</strong><p>Ser uma prova do Inep não torna a PND uma antecipação do Enem. Objetivos, candidatos e gêneros textuais são diferentes. Não há uma taxa de acerto validada para essa relação.</p></div></div><div className="dossier-note"><TriangleAlert size={18}/><p>Uma pista pública pode ajudar a escolher o que estudar. Ela não revela o tema reservado da prova.</p></div></section><aside className="dossier-aside"><section className="panel scenario"><span className="section-code">TESTE A HIPÓTESE</span><h3>Com e sem o sinal da PND</h3><p>Índice do tema “Leitura”, usando os mesmos pesos e as mesmas outras fontes.</p><div className="scenario-values"><div><span>Sem PND</span><strong>{fmt(readingWithout.percent)}<small>%</small></strong></div><ArrowRight size={20}/><div><span>Com PND</span><strong>{fmt(readingWith.percent)}<small>%</small></strong></div></div><div className="switch-label"><Switch id="pnd-signal" checked={institutional} onCheckedChange={setInstitutional}/><label htmlFor="pnd-signal">Usar provas relacionadas no ranking</label></div><p className="small-print">Este é o efeito da regra escolhida, não uma medição da chance de cair. Peso atual: {weights.institutional} pontos máximos; limite de 15.</p><button className="button primary full-width" onClick={()=>openTopic('leitura')}>Explorar leitura<ArrowRight size={16}/></button></section><section className="panel timeline"><span className="section-code">UM ANTECEDENTE</span><h3>A conexão de 2025</h3><div><span>PND 2025</span><p>Discussão sobre idadismo no contexto social e educacional.</p><LinkOut url={pnd2025PDF} className="text-link">Consultar caderno</LinkOut></div><div><span>ENEM 2025</span><p>Perspectivas acerca do envelhecimento na sociedade brasileira.</p><LinkOut url={officialSource} className="text-link">Consultar acervo</LinkOut></div><small>Uma aproximação temática em um ano é insuficiente para demonstrar um padrão. Este antecedente não soma pontos ao sinal de leitura.</small></section></aside></div></TabsContent>

 <TabsContent value="oficial"><div className="section-heading"><div><span className="section-code">03 / BIBLIOTECA ORIGINAL</span><h2>Direto da fonte</h2><p>Documentos e acervos do Inep para você conferir e estudar.</p></div><span className="tag">Curadoria · {day(BASE_DATE)}</span></div><div className="official-intro"><ShieldCheck size={21}/><p>“Oficial” identifica a origem do documento. Cartilhas e acervos orientam a preparação; não recebem bônus no ranking por serem oficiais.</p></div><div className="document-grid">{officialDocuments.map((d,i)=><article className="document-card panel" key={d.id}><div className="document-top"><span className="document-number">{String(i+1).padStart(2,'0')}</span><span className="tag">{d.tag} {d.year&&`/ ${d.year}`}</span></div><FileText className="document-icon" size={25}/><span className="document-type">{d.type}</span><h3>{d.title}</h3><p>{d.description}</p><small>{d.scope}</small><LinkOut url={d.url} className="document-link">Abrir no Inep</LinkOut></article>)}</div><div className="accessibility-note panel"><BookOpen size={24}/><div><h3>Cartilhas em formatos específicos</h3><p>O Inep também disponibiliza orientações para participantes com dislexia, surdez ou deficiência auditiva e TEA. Os downloads estão na página da cartilha.</p><LinkOut url={officialDocuments[0].url} className="text-link">Escolher a cartilha</LinkOut></div></div></TabsContent>

 <TabsContent value="fontes"><div className="section-heading"><div><span className="section-code">04 / RASTRO DE FONTES</span><h2>Todo sinal tem uma origem</h2><p>Curadoria, coleta automática e suas próprias pistas, identificadas em cada registro.</p></div><button className="button primary" onClick={()=>setAddOpen(true)}><Plus size={16}/>Adicionar fonte</button></div><div className="source-controls panel"><label className="search-field"><Search size={16}/><input aria-label="Buscar nas fontes" placeholder="Buscar título, resumo ou veículo…" value={sourceQuery} onChange={e=>setSourceQuery(e.target.value)}/></label><Select value={sourceFilter} onValueChange={setSourceFilter}><SelectTrigger aria-label="Filtrar tipo de fonte"><SelectValue/></SelectTrigger><SelectContent><SelectItem value="all">Todas as fontes</SelectItem>{(['editorial','news','institutional','hint'] as const).map(k=><SelectItem key={k} value={k}>{labels[k]}</SelectItem>)}<SelectItem value="personal">Adicionadas por você</SelectItem></SelectContent></Select><div className="switch-label"><Switch id="hints" checked={hints} onCheckedChange={setHints}/><label htmlFor="hints">Pistas não verificadas<span>Peso máximo: 5 pontos</span></label></div></div><details className="collection-status panel"><summary><RefreshCw size={16}/> {lastFetch?'Última consulta · '+day(lastFetch):'Status da coleta'}<ChevronDown size={16}/></summary><p>{portable?'No GitHub Pages, “Atualizar base” lê o arquivo publicado. Rode o script do projeto para coletar novas matérias.':'Coleta sob demanda com cache de até 15 minutos.'} Bloqueios e falhas não apagam a base anterior. São {monitored.length} fontes monitoradas; não é uma busca em toda a internet.</p>{monitored.map(s=>{const state=status.find(x=>x.id===s.id);return <div className="monitor-row" key={s.id}><LinkOut url={s.url}>{s.title}</LinkOut><span className={state?.ok?'success':state?'failure':''}>{state?.ok?<Check size={13}/>:state?<TriangleAlert size={13}/>:<Clock3 size={13}/>} {state?state.ok?`${state.count} registros · ${state.message}`:state.message:'Sem consulta nesta sessão'}</span></div>})}</details><div className="source-grid">{visibleSources.map(sourceCard)}</div>{!visibleSources.length&&<div className="empty-state panel"><Search size={29}/><h3>Nenhuma fonte neste filtro</h3><p>Tente outra busca ou acrescente uma matéria.</p><button className="button secondary" onClick={()=>{setSourceQuery('');setSourceFilter('all')}}>Limpar filtros</button></div>}<p className="local-note">Fontes pessoais e ajustes ficam neste navegador. Exportar e importar permitem levar sua análise para outro dispositivo.</p></TabsContent>

 <TabsContent value="historico"><div className="section-heading"><div><span className="section-code">05 / MEMÓRIA DO EXAME</span><h2>28 edições. Muitos caminhos.</h2><p>1998–2025 · aplicação regular principal · títulos resumidos</p></div><LinkOut url={officialSource} className="button secondary">Provas oficiais</LinkOut></div><div className="history-controls"><label className="search-field"><Search size={16}/><input aria-label="Buscar ano, tema ou eixo no histórico" placeholder="Buscar ano, tema ou eixo…" value={historyQuery} onChange={e=>setHistoryQuery(e.target.value)}/></label><p>Os eixos são editoriais. PPL, reaplicações, edições digitais e regionais não entram nesta série.</p></div><div className="history-grid">{[...historical].reverse().filter(h=>normalize(h.join(' ')).includes(normalize(historyQuery))).map(h=><article className={'history-card panel '+(h[0]===2006?'reading-year':'')} key={h[0]}><span className="history-year">{h[0]}</span><div><span className="history-axis">{h[2]}</span><h3>{h[1]}</h3>{h[0]===2006&&<span className="tag kind-institutional">Leitura já apareceu</span>}</div></article>)}</div>{!historical.some(h=>normalize(h.join(' ')).includes(normalize(historyQuery)))&&<div className="empty-state"><p>Nenhuma edição para esta busca.</p></div>}<div className="history-credit">Um tema antigo não recebe bônus por “estar atrasado”. Consulte a formulação integral no caderno. Fontes: <LinkOut url={historySource}>compilação histórica</LinkOut> <LinkOut url={guidanceSource}>Inep / cartilha 2026</LinkOut>.</div></TabsContent>

 <TabsContent value="plano"><div className="section-heading"><div><span className="section-code">06 / DA PISTA AO TEXTO</span><h2>Seu plano, seu ritmo.</h2><p>Salve os temas pelo marcador e transforme cada um em uma sessão de escrita.</p></div>{favorites.length>0&&<button className="button secondary" onClick={exportPlan}><Download size={16}/>Baixar plano</button>}</div>{favorites.length?<><div className="plan-progress panel"><CheckCheck size={23}/><div><strong>{favorites.filter(id=>completed.includes(id)).length} de {favorites.length} redações concluídas</strong><span>Revisar também faz parte da escrita.</span></div><div className="plan-progress-track"><span style={{width:favorites.filter(id=>completed.includes(id)).length/favorites.length*100+'%'}}/></div></div><div className="plan-grid">{favorites.map((id,i)=>{const t=ranking.find(r=>r.id===id)!;return <article className={'plan-card panel '+(completed.includes(id)?'plan-done':'')} key={id}><div className="source-top"><span className="section-code">SESSÃO {String(i+1).padStart(2,'0')}</span><button className="icon-button" aria-label={'Retirar '+t.title+' do plano'} onClick={()=>toggleFavorite(id)}><Trash2 size={16}/></button></div><h3>{t.title}</h3><p>{t.proposal}</p><ol className="session-steps"><li><span>10 min</span>Confira fontes e selecione repertórios</li><li><span>10 min</span>Organize tese, argumentos e intervenção</li><li><span>40 min</span>Escreva a redação</li><li><span>15 min</span>Revise com a cartilha do Inep</li></ol><div className="plan-card-bottom"><label><Checkbox checked={completed.includes(id)} onCheckedChange={v=>setCompleted(p=>v?[...new Set([...p,id])]:p.filter(x=>x!==id))}/>Texto concluído</label><button className="text-button" onClick={()=>openTopic(id)}>Ver fontes<ArrowUpRight size={14}/></button></div></article>})}</div></>:<div className="empty-plan panel"><Bookmark size={38}/><h3>Escolha o primeiro tema.</h3><p>Use o marcador na análise de um tema ou comece com os três primeiros do ranking atual.</p><div><button className="button primary" onClick={()=>setFavorites(ranking.slice(0,3).map(t=>t.id))}>Criar plano com o top 3<Plus size={16}/></button><button className="button secondary" onClick={()=>setTab('radar')}>Explorar radar</button></div></div>}</TabsContent>

 <TabsContent value="metodo"><div className="section-heading"><div><span className="section-code">07 / CÓDIGO ABERTO, REGRAS VISÍVEIS</span><h2>Cada número tem uma explicação.</h2><p>Modelo heurístico v2.0 · prioridade de estudo, sem calibração preditiva</p></div><button className="button secondary" onClick={()=>setSettingsOpen(true)}><SlidersHorizontal size={16}/>Ajustar pesos</button></div><div className="method-layout"><section className="panel method-main"><h3>Dos sinais à prioridade</h3><p>O radar compara {topics.length} temas escolhidos para esta versão. A redação real pode combinar assuntos ou tratar de outros temas. A seleção das fontes e os pesos influenciam os resultados.</p><div className="formula"><span>PONTOS DO TEMA</span><code>10 + {weights.editorial}E + {weights.news}A + {weights.history}H<br/>+ {institutional?weights.institutional:0}D + {hints?weights.hint:0}P</code><small>E: apostas · A: atualidades · H: histórico<br/>D: provas relacionadas · P: pistas não verificadas</small></div><ol className="method-steps"><li><strong>Classificar as evidências</strong><p>A base inicial tem curadoria. Coletas usam palavras-chave em títulos, descrições de feeds e seções de páginas; podem errar. A curadoria tem precedência sobre a classificação automática da mesma URL. Fontes pessoais ficam identificadas.</p></li><li><strong>Limitar repetição e envelhecimento</strong><p>URLs duplicadas são removidas. Por tema e categoria, vale a maior contribuição de cada grupo de domínio. gov.br conta como um grupo; uol.com.br também. É uma aproximação, sem detecção completa de republicações.</p><p>O peso de uma fonte cai pela metade a cada 180 dias. Sem data identificada, vale 0,5. Datas futuras e publicações com mais de dois anos são excluídas. E, A, D e P somam as contribuições por grupo, dividem por 3 e têm limite de 1.</p></li><li><strong>Usar o histórico como contexto</strong><p>H = (ocorrências do eixo + 1) ÷ (maior frequência de eixo + 1), nas edições regulares anteriores a {cutoff.slice(0,4)}. A classificação de eixos é editorial. Não há regra de alternância, nem bônus por tempo sem aparecer.</p></li><li><strong>Testar uma hipótese sem esconder o efeito</strong><p>Provas relacionadas podem ser desligadas e têm peso máximo de 15 pontos. O dossiê compara o cenário com e sem essa categoria. A cartilha e os acervos oficiais são referências de estudo, sem pontos automáticos.</p></li><li><strong>Normalizar</strong><p>Índice (%) = pontos do tema ÷ soma dos pontos de todos os temas × 100. Arredondamento por maiores restos mantém a soma em 100,0%. A base de 10 pontos evita tratar ausência de cobertura como impossibilidade.</p></li></ol></section><aside className="method-aside"><div className="panel"><ShieldCheck size={26}/><h3>O que o índice significa</h3><p>Este assunto reúne mais sinais nesta base, com estas regras e estes pesos.</p><p>Os pesos não foram treinados contra resultados futuros. Não há taxa de acerto ou probabilidade calibrada.</p></div><div className="panel"><TriangleAlert size={26}/><h3>Conheça os limites</h3><ul><li>A notoriedade de um assunto não revela a decisão do Inep.</li><li>Há viés de cobertura e de seleção dos temas.</li><li>Um antecedente da PND não estabelece um padrão.</li><li>Dados atuais não simulam previsões antigas.</li><li>Pistas não verificadas são opcionais e limitadas a 5 pontos.</li></ul></div><LinkOut url="https://github.com/THIAGO00199/RadarEnem" className="official-link"><Terminal size={22}/><span>Feito por Kaloré<small>Explore o código no GitHub</small></span></LinkOut></aside></div></TabsContent>
 </Tabs>
 <footer className="footer"><div className="footer-brand"><Terminal size={17}/><strong>kaloré</strong><span>Feito por Kaloré, para todos.</span></div><span>Fontes abertas. Pensamento crítico.</span><LinkOut url="https://github.com/THIAGO00199/RadarEnem">GitHub</LinkOut></footer></main>

 <Dialog open={compareOpen} onOpenChange={setCompareOpen}><DialogContent className="app-dialog compare-dialog"><DialogHeader><DialogTitle>Dois temas. Mais contexto.</DialogTitle><DialogDescription>Compare os sinais para escolher o próximo treino. Os índices representam prioridade nesta base; não são chances de cair.</DialogDescription></DialogHeader><div className="compare-pickers">{compareIds.map((id,i)=><label key={i}><span>Tema {i+1}</span><Select value={id} onValueChange={v=>setCompareIds(p=>i===0?[v,p[1]]:[p[0],v])}><SelectTrigger aria-label={'Tema '+(i+1)+' da comparação'}><SelectValue/></SelectTrigger><SelectContent>{topics.map(t=><SelectItem key={t.id} value={t.id}>{t.title}</SelectItem>)}</SelectContent></Select></label>)}</div>{compareIds[0]===compareIds[1]&&<p className="comparison-same" role="status">Você selecionou o mesmo tema. Escolha outro para comparar.</p>}<div className="compare-grid">{comparison.map((t,i)=><article className="compare-card" key={i}><span className="eyebrow">{t.axis}</span><h3>{t.title}</h3><div className="compare-index"><strong>{fmt(t.percent)}<span>%</span></strong><span>índice relativo de estudo</span></div><p>{t.groups} grupos de fontes · {t.related.length} evidências</p><dl className="compare-factors">{weightKeys.map(k=><div key={k}><dt>{labels[k]}</dt><dd>+{fmt(t.points[k])}</dd></div>)}</dl><p className="compare-proposal">{t.proposal}</p><button className="button secondary full-width" onClick={()=>toggleFavorite(t.id)}>{favorites.includes(t.id)?<Check size={16}/>:<Bookmark size={16}/>} {favorites.includes(t.id)?'No meu plano':'Salvar para estudar'}</button><a className="button primary full-width" href={'./estudar.html?tema='+encodeURIComponent(t.proposal)+'#redacao'}>Treinar redação<ArrowUpRight size={16}/></a></article>)}</div><div className="dialog-actions"><button className="button secondary" onClick={exportComparison}><Download size={16}/>Exportar comparação</button><button className="button primary" onClick={()=>setCompareOpen(false)}>Pronto<Check size={16}/></button></div></DialogContent></Dialog>
 <Dialog open={settingsOpen} onOpenChange={setSettingsOpen}><DialogContent className="app-dialog"><DialogHeader><DialogTitle>Ajuste a intensidade dos sinais</DialogTitle><DialogDescription>O ranking responde imediatamente. Os ajustes ficam neste navegador.</DialogDescription></DialogHeader><div className="weight-controls">{weightKeys.map(k=><div key={k}><label htmlFor={'weight-'+k}>{labels[k]}<strong>{weights[k]} pts</strong></label><Slider id={'weight-'+k} aria-label={labels[k]} value={[weights[k]]} min={0} max={k==='hint'?5:k==='institutional'?15:100} step={1} onValueChange={v=>setWeights(w=>({...w,[k]:v[0]}))}/></div>)}</div><div className="settings-toggles"><div className="switch-label"><Switch id="pnd-settings" checked={institutional} onCheckedChange={setInstitutional}/><label htmlFor="pnd-settings">Incluir provas relacionadas</label></div><div className="switch-label"><Switch id="hint-settings" checked={hints} onCheckedChange={setHints}/><label htmlFor="hint-settings">Incluir pistas não verificadas</label></div><div className="switch-label"><Switch id="motion-settings" checked={animations} onCheckedChange={setAnimations}/><label htmlFor="motion-settings">Animações decorativas</label></div></div><p className="small-print">A preferência de movimento reduzido do dispositivo é sempre respeitada. Pistas estão desligadas por padrão.</p><div className="dialog-actions"><button className="button secondary" onClick={()=>{setWeights(defaultWeights);setHints(false);setInstitutional(true)}}>Restaurar pesos</button><button className="button primary" onClick={()=>setSettingsOpen(false)}>Pronto<Check size={16}/></button></div></DialogContent></Dialog>
 <Dialog open={addOpen} onOpenChange={setAddOpen}><DialogContent className="app-dialog add-dialog"><DialogHeader><DialogTitle>Acrescente um sinal ao radar</DialogTitle><DialogDescription>Uma matéria, análise de prova ou pista pública. Sua contribuição fica identificada.</DialogDescription></DialogHeader><form onSubmit={submit}><label>Título<input required minLength={5} maxLength={280} value={title} onChange={e=>setTitle(e.target.value)} placeholder="Ex.: estudo sobre acesso a bibliotecas"/></label><label>Link da fonte <span>(opcional)</span><input type="url" maxLength={2000} value={url} onChange={e=>setUrl(e.target.value)} placeholder="https://…"/></label><div className="form-pair"><label>Tipo de evidência<Select value={kind} onValueChange={v=>setKind(v as Kind)}><SelectTrigger><SelectValue/></SelectTrigger><SelectContent>{(['hint','editorial','news','institutional'] as const).map(k=><SelectItem key={k} value={k}>{labels[k]}</SelectItem>)}</SelectContent></Select></label><label>Data de publicação<input type="date" max={today()} value={date} onChange={e=>setDate(e.target.value)}/></label></div><label>Resumo <span>(opcional)</span><textarea maxLength={1800} rows={3} value={text} onChange={e=>setText(e.target.value)} placeholder="Por que essa fonte se relaciona com o tema?"/></label><div className="topic-choice-title"><strong>Temas relacionados</strong><button type="button" className="text-button" onClick={()=>{const found=classify(title+' '+text);setChosen(found);setFormError(found.length?'':'Nenhuma palavra-chave reconhecida. Marque os temas abaixo.')}}><Search size={14}/>Sugerir pelo texto</button></div><div className="topic-checks">{topics.map(t=><label key={t.id}><Checkbox checked={chosen.includes(t.id)} onCheckedChange={v=>setChosen(p=>v?[...new Set([...p,t.id])]:p.filter(x=>x!==t.id))}/><span>{t.title}</span></label>)}</div>{formError&&<p role="alert" className="form-error">{formError}</p>}<p className="small-print">Sem data, a contribuição é reduzida. Adicionar um link não verifica ou importa seu conteúdo. Escolher “Provas relacionadas” também não torna a fonte oficial.</p><button className="button primary full-width" type="submit">Adicionar ao radar<Plus size={16}/></button></form></DialogContent></Dialog>
 </div>;
}
